WITH employees_by_department AS (SELECT dept_id, AVG(salary) AS avg_salary FROM employees GROUP BY dept_id) SELECT departments.id, departments.budget, departments.dept_name, employees_by_department.avg_salary FROM departments INNER JOIN employees_by_department ON departments.id = employees_by_department.dept_id WHERE employees_by_department.avg_salary > 113000 ORDER BY departments.dept_name ASC, id ASC LIMIT 50;
